// The display-composition seam (browse-scale 1.1): the pure composer core
// lives in internal/naming (moved verbatim — the precedence chains, the
// element-template grammar, and the dynamic document accessors are the
// naming package's now); what stays api-side are the three app methods that
// read a.deps — namerFor (the per-library construction over GetLibrary +
// QuerySeries + elementTemplate), elementTemplate (the library option over
// the module default), and withSeriesOverride (the per-row series-override
// point read over a.storedTitle) — the app-shaped legs the pure composer
// must never carry. `titleSourceBinding` (handlers.go) aliases
// naming.TitleSourceBinding, so every api signature, JSON tag, and cmd
// closure call is byte-identical. Composition is read-time and never
// persisted; the precedence chains are byte-for-byte the SPA's
// (Home.tsx seriesDisplayTitle and continueTitle's compose branch).
//
// Cyrillic — and any non-ASCII text — passes through the whole chain
// VERBATIM: no normalization, no transliteration, no reformatting anywhere
// in the composer; document strings are compared and emitted as the exact
// bytes the parsers wrote. A name that cannot resolve from facts floors
// honestly ("" at the bottom) — the composer never fabricates one.

package api

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/naming"
	"github.com/mellifera/mellifera/internal/store"
)

// namerFor builds the namer for one library: GetLibrary carries the two
// naming options, plus ONE QuerySeries(libraryID, "") whole-table read mapped
// by RelativePath (mirrors the SPA's matchSeries input). mutes is the
// calling Viewer's ChainMutes (l6-accounts 10.4) — callers pass v.ChainMutes
// off the viewerFor they already resolved (no fresh context read here); nil
// is the mute-blind floor the admin/write call sites keep. A MISSING library row
// floors to the empty namer — the one floor EVERY namerFor call site shares,
// so a vanished library row can never turn a previously-200 route into a 500:
// ElementTmpl "" means no composition, and display_name renders from the
// floor tiers ("" when nothing resolves), exactly like the listItems browse
// contract for a nonexistent ?library=. Any OTHER store error propagates to
// the caller (the handlers map it → 500, like any other read).
//
// Flag-(i) per-site re-derivation (the two access.System() reads 6.2
// documented as deliberately unthreaded — 10.4 owns this neighborhood):
// BOTH reads stay System() on purpose. The mute floor floors source
// NAMESPACES in the walk, never rows: GetLibrary re-reads the one library
// row the calling handler already admitted the viewer to (an invisible
// library 404s upstream of every namerFor), and QuerySeries is the
// whole-library series map (D-9) — every row in it belongs to that same
// admitted library, so a viewer-scoped re-filter could only re-drop rows
// the caller already vetted, never change a name. Row visibility is the
// Viewer's VisibleLibraryIDs contract and lives at the caller; only the
// title walk below carries the mutes.
func (a *app) namerFor(ctx context.Context, libraryID int64, mutes map[string]bool) (naming.Namer, error) {
	lib, err := a.deps.Store.GetLibrary(ctx, libraryID, access.System())
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return naming.Namer{}, nil
		}
		return naming.Namer{}, err
	}
	rows, err := a.deps.Store.QuerySeries(ctx, libraryID, "", access.System())
	if err != nil {
		return naming.Namer{}, err
	}
	byPath := make(map[string]store.Series, len(rows))
	for _, sr := range rows {
		byPath[sr.RelativePath] = sr
	}
	tmpl, pres, err := a.elementTemplate(ctx, lib)
	if err != nil {
		return naming.Namer{}, err
	}
	return naming.Namer{
		GroupStyle:   lib.NamingGroupStyle,
		ElementTmpl:  tmpl,
		SeriesByPath: byPath,
		TitleSources: pres.TitleSources,
		LangPrefs:    pres.LanguagePreference,
		Chain:        pres.SourceChain,
		ModuleID:     lib.ModuleID,
		Mutes:        mutes,
	}, nil
}

// elementTemplate resolves the ACTIVE element template for a library row:
// the library's own naming_element_name option when set, ELSE the module
// default (ModulePresentation.ItemName through the Deps closure), else ""
// (no composition). It returns the presentation alongside the template: the
// SAME closure call carries the title-walk inputs (TitleSources/
// LanguagePreference, plugin-title-enrichment D5) — scoped to THIS library's
// id, the gate-resolution scope — so namerFor gets both
// from one read even when the library option wins the template — the walk
// is module config, not a composition option, and applies either way. A nil
// closure is the zero presentation (no default template, empty walk); a
// closure error is a real failure and propagates to the caller (the
// handlers map it, like any other read).
func (a *app) elementTemplate(ctx context.Context, lib store.Library) (string, ModulePresentation, error) {
	if a.deps.ModulePresentation == nil {
		return lib.NamingElementName, ModulePresentation{}, nil
	}
	mp, err := a.deps.ModulePresentation(ctx, lib.ModuleID, lib.ID)
	if err != nil {
		return "", ModulePresentation{}, err
	}
	tmpl := lib.NamingElementName
	if tmpl == "" {
		tmpl = mp.ItemName
	}
	return tmpl, mp, nil
}

// withSeriesOverride point-reads the resolved series' stored title override
// for one item row and returns the namer carrying it — a point read beside
// the row's own, the exact per-row override posture storedTitle already uses
// (display-naming D-9 prices these per-series reads). Rows that never reach
// the series tier — no template, no facts, unresolved or tombstoned series —
// return the namer unchanged; a store failure propagates (500 at the call
// site), like any other override read.
func (a *app) withSeriesOverride(ctx context.Context, n naming.Namer, doc json.RawMessage) (naming.Namer, error) {
	sr, _, _, ok := n.ElementFacts(naming.DocMap(doc))
	if !ok {
		return n, nil
	}
	so, err := a.storedTitle(ctx, sr.ID)
	if err != nil {
		return naming.Namer{}, err
	}
	n.SeriesOverride = so
	return n, nil
}
